assert.equal(engine._cu_init(allocate(optical),optical.byteLength),0);
const galaxy=allocate(await readFile(new URL('../artifacts/galaxy.bin',import.meta.url)));
const params=allocate(new Uint8Array(new Float64Array(16).buffer));
const cols=96,rows=48,n=cols*rows;
function frame(yaw=Math.PI,pitch=-Math.atan2(4,24)){
  assert.equal(engine._cu_frame(cols,rows,0,4,24,yaw,pitch,55,.713,1,1,0),0,engine.UTF8ToString(engine._cu_error()));
  return {output:engine.HEAPU8.slice(engine._cu_output(),engine._cu_output()+7*n),
    mask:engine.HEAPU8.slice(engine._cu_mask(),engine._cu_mask()+n),
    objects:engine.HEAPU8.slice(engine._cu_object_mask(),engine._cu_object_mask()+n),
    stats:engine.HEAPF32.slice(engine._cu_stats()>>2,(engine._cu_stats()>>2)+12)};
}
const baseline=frame().output;
engine._cu_set_overlay(1);
assert.equal(engine._cu_set_environment(galaxy,1024,512,params),0);
const lensed=frame();assert.equal(lensed.stats[8],1);assert.ok(lensed.stats[9]>0&&lensed.stats[10]>0);
assert.ok(lensed.mask.every(x=>x===255));assert.ok(lensed.objects.some(x=>x===0));assert.ok(lensed.objects.some(x=>x===255));
assert.deepEqual(frame().output,lensed.output);
assert.equal(engine._cu_set_lens_strength(0),0);
const straight=frame();assert.equal(straight.stats[11],0);assert.ok(straight.objects.every(x=>x===0));
assert.ok(straight.mask.every(x=>x===255));assert.ok(straight.output.subarray(0,n).every(x=>[32,46,58,42,43,35].includes(x)));
assert.equal(engine._cu_set_lens_strength(.5),0);
const halfway=frame();assert.equal(halfway.stats[11],.5);assert.ok(halfway.objects.some(x=>x>0&&x<255));
assert.ok(halfway.mask.every(x=>x===255));assert.notDeepEqual(halfway.output,straight.output);assert.notDeepEqual(halfway.output,lensed.output);
assert.equal(engine._cu_set_lens_strength(1),0);assert.deepEqual(frame().output,lensed.output);
const away=frame(0,0);assert.ok(away.objects.every(x=>x===0));assert.ok(away.output.subarray(0,n).some(x=>x!==32));
assert.ok(away.mask.every(x=>x===255));
const spatialBytes=await readFile(new URL('../artifacts/galaxy-stars.bin',import.meta.url));
const spatialPointer=allocate(spatialBytes);
assert.equal(engine._cu_set_galaxy(spatialPointer,spatialBytes.length/32,params),0);
const spatial=frame();assert.ok(spatial.mask.every(x=>x===255));
assert.ok(spatial.output.subarray(0,n).filter((x,i)=>x!==32&&spatial.objects[i]===0).length>20);
new Float64Array(engine.HEAPU8.buffer,params,3).set([2,0,0]);
assert.equal(engine._cu_set_galaxy(spatialPointer,spatialBytes.length/32,params),0);
const displaced=frame();assert.notDeepEqual(displaced.output,spatial.output);
assert.equal(engine._cu_set_galaxy(0,0,params),0);
assert.equal(engine._cu_set_environment(0,0,0,0),0);engine._cu_set_overlay(0);
assert.deepEqual(frame().output,baseline);
console.log(JSON.stringify({passed:true,escapingSkyCells:lensed.stats[9],capturedCells:lensed.stats[10],objectOnlyPicking:true,finitePointParallax:true,defaultRestored:true}));

// Regression: the real Grand Tour departure that formerly exhausted WASM
// while growing a contiguous buffer beyond 524,288 projected catalog stars.
import {Worker,isMainThread,parentPort} from 'node:worker_threads';
import {readFile} from 'node:fs/promises';
import assert from 'node:assert/strict';
if(!isMainThread){
 globalThis.self={postMessage:(data,transfer)=>parentPort.postMessage(data,transfer)};
 globalThis.fetch=async url=>new Response(await readFile(new URL(`..${url}`,import.meta.url)));
 await import('../web/atlas-worker.js');
 parentPort.on('message',data=>self.onmessage({data}));
}else{
 const worker=new Worker(new URL(import.meta.url));let id=0;const pending=new Map(),report=[];
 worker.on('message',data=>{const p=pending.get(data.id);if(!p)return;pending.delete(data.id);data.type==='error'?p.reject(Object.assign(Error(data.error),data)):p.resolve(data);});
 worker.on('error',error=>{for(const p of pending.values())p.reject(error);});
 const request=data=>new Promise((resolve,reject)=>{const key=++id;pending.set(key,{resolve,reject});worker.postMessage({...data,id:key});});
 try{
  await request({type:'init'});
  const state=JSON.parse(await readFile(new URL('./orion-departure-state.json',import.meta.url)));
  const destinations=JSON.parse(await readFile(new URL('../artifacts/phenomena-destinations.json',import.meta.url))).destinations;
  await request({type:'prepare-destination',destination:destinations.find(d=>d.id==='crab-pulsar')});
  const frame=async s=>{
   const f=await request({type:'frame',state:s});
   assert.ok(!f.stats.local_error,f.stats.local_error);
   assert.equal(f.buffer.byteLength,s.cols*s.rows*7);
   assert.ok(f.stats.heap_bytes<256*1024**2,'Atlas plus phenomenon engine stays within 256 MiB');
   report.push({grid:[s.cols,s.rows],stars:f.stats.projected_stars,heapBytes:f.stats.heap_bytes,ms:f.stats.frame_ms});
   return f;
  };
  const original=await frame(state);
  assert.ok(original.stats.projected_stars>524288,'Exercise the old failing allocation without removing stars');
  const wide={...state,cols:320,rows:160,fov:35,yaw:Math.atan2(-state.position[0],-state.position[2]),pitch:Math.asin(-state.position[1]/Math.hypot(...state.position))};
  const maximum=await frame(wide);
  assert.ok(maximum.stats.projected_stars>780000,`A centered view must exercise nearly the entire nearby Gaia sample (${maximum.stats.projected_stars})`);
  await frame({...state,cols:96,rows:48});
  const back=await frame(state);
  assert.deepEqual(new Uint8Array(back.buffer),new Uint8Array(original.buffer),'Page reuse and resizing must retain every character/color');
  const stable=await frame(wide);
  assert.deepEqual(new Uint8Array(stable.buffer),new Uint8Array(maximum.buffer));
  const repeat=await frame(wide);
  assert.equal(repeat.stats.heap_bytes,stable.stats.heap_bytes,'A stationary dense view must reuse allocations');
  console.log(JSON.stringify({passed:true,frames:report},null,2));
 }finally{await worker.terminate();}
}

"""CPU-only checks for the direct-cell illustrative phenomenon interpreter."""
import ctypes as ct
from pathlib import Path
import unittest
import numpy as np

ROOT=Path(__file__).resolve().parents[1]
LIBRARY=ROOT/'native/build/libuniverse_phenomena.so'


class NativePhenomena:
    def __init__(self):
        self.lib=ct.CDLL(str(LIBRARY))
        self.lib.phenomena_init.argtypes=[ct.c_void_p,ct.c_uint32]
        self.lib.phenomena_frame.argtypes=[ct.c_int]*3+[ct.c_double]*5
        self.lib.phenomena_frame_camera.argtypes=[ct.c_int]*3+[ct.c_double]*8
        self.lib.phenomena_output.restype=ct.POINTER(ct.c_uint8)
        self.lib.phenomena_mask.restype=ct.POINTER(ct.c_uint8)
        self.lib.phenomena_stats.restype=ct.POINTER(ct.c_float)
        self.lib.phenomena_error.restype=ct.c_char_p
        self.lib.phenomena_shutdown()
        data=(ROOT/'artifacts/phenomena.bin').read_bytes()
        self.asset=ct.create_string_buffer(data)
        assert self.lib.phenomena_init(self.asset,len(data))==0,self.lib.phenomena_error()

    def frame(self,scene=0,yaw=.25,pitch=.18,distance=5.,time=0.,cols=128,rows=64):
        assert self.lib.phenomena_frame(cols,rows,scene,yaw,pitch,distance,time,1.)==0,self.lib.phenomena_error()
        return (np.ctypeslib.as_array(self.lib.phenomena_output(),shape=(cols*rows*7,)).copy(),
                np.ctypeslib.as_array(self.lib.phenomena_stats(),shape=(4,)).copy())


@unittest.skipUnless(LIBRARY.exists(),'Build native/build_phenomena.py --native')
class TestPhenomena(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.engine=NativePhenomena()

    def test_all_six_scenes_have_visible_colored_cells(self):
        for scene in range(6):
            with self.subTest(scene=scene):
                data,stats=self.engine.frame(scene)
                n=128*64
                self.assertGreater(np.count_nonzero(data[:n]!=32),n*.025)
                self.assertGreater(np.max(data[n:n*4]),100)
                self.assertEqual(stats[2],n)
                self.assertEqual(stats[3],scene)
                self.assertTrue(np.all((data[:n]>=32)&(data[:n]<=126)))
                self.assertGreater(stats[0],0)
                self.assertEqual(stats[1]>0,scene in (2,3))

    def test_identical_state_is_byte_reproducible(self):
        for scene in range(6):
            a,_=self.engine.frame(scene,time=2.137)
            b,_=self.engine.frame(scene,time=2.137)
            np.testing.assert_array_equal(a,b)

    def test_free_orbit_reprojects_compiled_volume_in_three_dimensions(self):
        for scene in (2,3):
            a,_=self.engine.frame(scene,yaw=.17,pitch=.1)
            b,_=self.engine.frame(scene,yaw=.73,pitch=.4)
            self.assertGreater(np.mean(a!=b),.10)

    def test_dynamic_surface_and_beam_families_animate(self):
        for scene in (0,1,4,5):
            a,_=self.engine.frame(scene,time=0)
            b,_=self.engine.frame(scene,time=4.7)
            self.assertGreater(np.mean(a!=b),.01)

    def test_static_volume_cache_is_valid_across_time_and_other_scene_renders(self):
        lib=self.engine.lib;cols,rows=81,41;n=cols*rows
        for scene in (2,3):
            for position in ((.2,.1,.3),(0.,.3,5.)):
                expected=None
                for time in (0.,17.3,913.7):
                    self.engine.frame(4,time=time,cols=cols,rows=rows)
                    self.assertEqual(lib.phenomena_frame_camera(cols,rows,scene,*position,.17,-.1,54.,time,1.),0)
                    result=np.concatenate((np.ctypeslib.as_array(lib.phenomena_output(),shape=(n*7,)),
                                           np.ctypeslib.as_array(lib.phenomena_mask(),shape=(n,)))).copy()
                    if expected is None:expected=result
                    else:np.testing.assert_array_equal(result,expected)

    def test_resize_and_camera_inside_volume(self):
        for scene in range(6):
            data,stats=self.engine.frame(scene,distance=.8,cols=320,rows=160)
            self.assertEqual(len(data),320*160*7)
            self.assertTrue(np.isfinite(stats).all())
        self.assertNotEqual(self.engine.lib.phenomena_frame(0,0,0,0.,0.,5.,0.,1.),0)


